BEGIN;

WITH catalog(key, name, description, difficulty, equipment, muscles, goals) AS (
  VALUES
    ('hack-squat', 'Гакк-приседания', 'Опускайте и поднимайте каретку, сохраняя спину на опоре.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('smith-squat', 'Приседания в тренажёре Смита', 'Приседайте с грифом, который движется по направляющим.', 'intermediate', ARRAY['Тренажёр', 'Тренажёр Смита'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('hip-abduction', 'Разведение ног в тренажёре', 'Сидя разводите колени, преодолевая сопротивление боковых подушек.', 'beginner', ARRAY['Тренажёр'], ARRAY['Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('hip-adduction', 'Сведение ног в тренажёре', 'Сводите бёдра к центру, нажимая на подушки внутренней стороной коленей.', 'beginner', ARRAY['Тренажёр'], ARRAY['Приводящие мышцы бедра'], ARRAY['Сила', 'Общий тонус']),
    ('glute-drive', 'Ягодичный мост в тренажёре', 'Поднимайте таз, перемещая рычаг с упором на бёдрах.', 'beginner', ARRAY['Тренажёр'], ARRAY['Ягодичные мышцы', 'Задняя поверхность бедра'], ARRAY['Сила', 'Общий тонус']),
    ('glute-kickback', 'Отведение ноги назад в тренажёре', 'Отводите бедро назад, выталкивая платформу одной ногой.', 'beginner', ARRAY['Тренажёр'], ARRAY['Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('seated-calf', 'Подъёмы на носки сидя в тренажёре', 'Поднимайте пятки, перемещая вверх упор на бёдрах.', 'beginner', ARRAY['Тренажёр'], ARRAY['Икроножные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('sled-calf', 'Жим носками на платформе', 'Двигайте платформу жима ногами за счёт движения в голеностопах.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Икроножные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('belt-squat', 'Приседания в поясном тренажёре', 'Приседайте с отягощением, прикреплённым к поясу.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('single-leg-press', 'Жим платформы одной ногой', 'Выжимайте платформу одной стопой, сохраняя таз на сиденье.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-chest', 'Жим от груди в тренажёре', 'Сидя выжимайте рукояти вперёд от груди.', 'beginner', ARRAY['Тренажёр'], ARRAY['Грудные мышцы', 'Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('incline-machine', 'Наклонный жим в рычажном тренажёре', 'Выжимайте рычаги вперёд и вверх от верхней части груди.', 'beginner', ARRAY['Тренажёр'], ARRAY['Грудные мышцы', 'Дельтовидные мышцы', 'Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('pec-deck', 'Сведение рук в тренажёре «Бабочка»', 'Сводите рычаги перед грудью, сохраняя спину на опоре.', 'beginner', ARRAY['Тренажёр'], ARRAY['Грудные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('reverse-pec-deck', 'Обратная «бабочка»', 'Сядьте лицом к спинке и разводите рукояти в стороны.', 'beginner', ARRAY['Тренажёр'], ARRAY['Дельтовидные мышцы', 'Ромбовидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-shoulder', 'Жим вверх в тренажёре на плечи', 'Поднимайте рукояти от уровня плеч вверх.', 'beginner', ARRAY['Тренажёр'], ARRAY['Дельтовидные мышцы', 'Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-lateral', 'Разведение рук в тренажёре на плечи', 'Разводите локти в стороны, поднимая рычаги тренажёра.', 'beginner', ARRAY['Тренажёр'], ARRAY['Дельтовидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-row', 'Рычажная тяга с упором грудью', 'Прижмите грудь к опоре и тяните рукояти к корпусу.', 'beginner', ARRAY['Тренажёр'], ARRAY['Широчайшие мышцы спины', 'Ромбовидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-pullover', 'Пуловер в тренажёре', 'Из верхнего положения опускайте рычаг по дуге к бёдрам.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Широчайшие мышцы спины'], ARRAY['Сила', 'Общий тонус']),
    ('assisted-pullup', 'Подтягивания в гравитроне', 'Подтягивайтесь к перекладине с противовесом под коленями.', 'beginner', ARRAY['Тренажёр', 'Гравитрон'], ARRAY['Широчайшие мышцы спины', 'Бицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('assisted-dip', 'Отжимания на брусьях в гравитроне', 'Разгибайте руки на брусьях с поддержкой подвижной платформы.', 'beginner', ARRAY['Тренажёр', 'Гравитрон'], ARRAY['Трицепсы', 'Грудные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-preacher', 'Сгибание рук в тренажёре на бицепс', 'Прижмите плечи к наклонной подушке и поднимайте рукояти.', 'beginner', ARRAY['Тренажёр'], ARRAY['Бицепсы', 'Плечевые мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-dip', 'Жим вниз в тренажёре на трицепс', 'Сидя на тренажёре опускайте рукояти по сторонам от корпуса.', 'beginner', ARRAY['Тренажёр'], ARRAY['Трицепсы', 'Грудные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('machine-crunch', 'Скручивания в тренажёре', 'Сгибайте корпус, сближая грудную клетку и таз против сопротивления.', 'beginner', ARRAY['Тренажёр'], ARRAY['Прямая мышца живота'], ARRAY['Сила', 'Общий тонус']),
    ('rotary-torso', 'Повороты корпуса в тренажёре', 'Поворачивайте подвижную часть тренажёра относительно неподвижной опоры.', 'intermediate', ARRAY['Тренажёр'], ARRAY['Косые мышцы живота'], ARRAY['Сила', 'Общий тонус']),
    ('machine-back-extension', 'Разгибание спины в тренажёре сидя', 'Из наклона выпрямляйте корпус, надавливая спиной на валик.', 'beginner', ARRAY['Тренажёр'], ARRAY['Разгибатели спины'], ARRAY['Сила', 'Общий тонус']),
    ('cable-kickback', 'Отведение ноги назад на блоке', 'Закрепите манжету на щиколотке и отводите ногу назад.', 'beginner', ARRAY['Блочный тренажёр'], ARRAY['Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('cable-hip-abduction', 'Отведение ноги в сторону на блоке', 'Стоя боком к нижнему блоку, отводите ногу с манжетой в сторону.', 'beginner', ARRAY['Блочный тренажёр'], ARRAY['Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('cable-pull-through', 'Тяга нижнего блока между ног', 'Стоя спиной к блоку, разгибайте бёдра с канатом между ног.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Ягодичные мышцы', 'Задняя поверхность бедра'], ARRAY['Сила', 'Общий тонус']),
    ('straight-arm-pulldown', 'Тяга верхнего блока прямыми руками', 'Опускайте рукоять по дуге к бёдрам при небольшом сгибе локтей.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Широчайшие мышцы спины'], ARRAY['Сила', 'Общий тонус']),
    ('one-arm-pulldown', 'Тяга верхнего блока одной рукой', 'Тяните одиночную рукоять сверху, направляя локоть к боку.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Широчайшие мышцы спины', 'Бицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('cable-lateral', 'Подъём руки в сторону на нижнем блоке', 'Стоя боком к блоку, поднимайте рукоять в сторону.', 'beginner', ARRAY['Блочный тренажёр'], ARRAY['Дельтовидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('cable-curl', 'Сгибание рук на нижнем блоке', 'Сгибайте локти, поднимая рукоять нижнего блока к плечам.', 'beginner', ARRAY['Блочный тренажёр'], ARRAY['Бицепсы', 'Плечевые мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('overhead-cable', 'Разгибание рук с канатом из-за головы', 'Отвернитесь от блока и разгибайте локти, перемещая канат из-за головы.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('cable-crunch', 'Скручивания на верхнем блоке', 'Стоя на коленях с канатом у головы, сгибайте корпус.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Прямая мышца живота'], ARRAY['Сила', 'Общий тонус']),
    ('cable-chop', 'Диагональная тяга на блоке', 'Перемещайте рукоять от высокого блока к противоположному бедру.', 'intermediate', ARRAY['Блочный тренажёр'], ARRAY['Косые мышцы живота'], ARRAY['Сила', 'Общий тонус']),
    ('pallof-press', 'Жим Паллофа на блоке', 'Стоя боком к блоку, выпрямляйте руки перед грудью и удерживайте корпус от поворота.', 'beginner', ARRAY['Блочный тренажёр'], ARRAY['Косые мышцы живота', 'Прямая мышца живота'], ARRAY['Сила', 'Общий тонус']),
    ('front-squat', 'Фронтальные приседания', 'Приседайте с грифом на передней части плеч.', 'advanced', ARRAY['Штанга'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('sumo-deadlift', 'Становая тяга сумо', 'Поднимайте штангу с пола в широкой стойке с хватом между ног.', 'advanced', ARRAY['Штанга'], ARRAY['Ягодичные мышцы', 'Приводящие мышцы бедра', 'Квадрицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('barbell-row', 'Тяга штанги в наклоне', 'Удерживая наклон корпуса, подтягивайте гриф к поясу.', 'intermediate', ARRAY['Штанга'], ARRAY['Широчайшие мышцы спины', 'Ромбовидные мышцы', 'Бицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('standing-press', 'Жим штанги стоя', 'Выжимайте гриф от плеч вверх из положения стоя.', 'intermediate', ARRAY['Штанга'], ARRAY['Дельтовидные мышцы', 'Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('barbell-curl', 'Сгибание рук со штангой', 'Поднимайте гриф к груди, сгибая руки в локтях.', 'beginner', ARRAY['Штанга'], ARRAY['Бицепсы', 'Плечевые мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('db-fly', 'Разведение гантелей лёжа', 'Лёжа на скамье, разводите гантели по дуге и сводите их над грудью.', 'intermediate', ARRAY['Гантели', 'Скамья'], ARRAY['Грудные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('db-shrug', 'Шраги с гантелями', 'Держа гантели по сторонам, поднимайте и опускайте плечи.', 'beginner', ARRAY['Гантели'], ARRAY['Трапециевидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('db-skullcrusher', 'Французский жим с гантелями лёжа', 'Лёжа на скамье, опускайте гантели по сторонам головы и разгибайте локти.', 'intermediate', ARRAY['Гантели', 'Скамья'], ARRAY['Трицепсы'], ARRAY['Сила', 'Общий тонус']),
    ('single-leg-rdl', 'Румынская тяга на одной ноге с гантелями', 'Наклоняйтесь на опорной ноге, отводя свободную ногу назад.', 'intermediate', ARRAY['Гантели'], ARRAY['Задняя поверхность бедра', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('db-walking-lunge', 'Выпады в ходьбе с гантелями', 'Шагайте вперёд попеременно каждой ногой, опускаясь в выпад с гантелями.', 'intermediate', ARRAY['Гантели'], ARRAY['Квадрицепсы', 'Ягодичные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('band-pull-apart', 'Разведение рук с резинкой перед собой', 'Растягивайте резинку в стороны перед грудью.', 'beginner', ARRAY['Фитнес-резинка'], ARRAY['Дельтовидные мышцы', 'Ромбовидные мышцы'], ARRAY['Сила', 'Общий тонус']),
    ('band-leg-curl', 'Сгибание ноги с резинкой лёжа', 'Лёжа на животе, сгибайте колено против натяжения закреплённой резинки.', 'beginner', ARRAY['Фитнес-резинка'], ARRAY['Задняя поверхность бедра'], ARRAY['Сила', 'Общий тонус']),
    ('single-leg-bridge', 'Ягодичный мост на одной ноге', 'Поднимайте таз с опорой на одну стопу, удерживая другую ногу на весу.', 'intermediate', ARRAY['Собственный вес'], ARRAY['Ягодичные мышцы', 'Задняя поверхность бедра'], ARRAY['Общий тонус', 'Выносливость']),
    ('reverse-crunch', 'Обратные скручивания', 'Лёжа на спине, подкручивайте таз и приближайте колени к груди.', 'beginner', ARRAY['Собственный вес'], ARRAY['Прямая мышца живота'], ARRAY['Общий тонус', 'Выносливость']),
    ('side-plank-dip', 'Подъёмы таза в боковой планке', 'Из боковой опоры на предплечье опускайте и поднимайте таз.', 'intermediate', ARRAY['Собственный вес'], ARRAY['Косые мышцы живота', 'Ягодичные мышцы'], ARRAY['Общий тонус', 'Выносливость']),
    ('heel-taps', 'Касания пяток лёжа', 'Приподнимите лопатки и поочерёдно тянитесь руками к пяткам.', 'beginner', ARRAY['Собственный вес'], ARRAY['Косые мышцы живота', 'Прямая мышца живота'], ARRAY['Общий тонус', 'Выносливость']),
    ('skater-hop', 'Прыжки конькобежца', 'Перепрыгивайте с ноги на ногу в стороны, удерживая равновесие после приземления.', 'intermediate', ARRAY['Собственный вес'], ARRAY['Ягодичные мышцы', 'Квадрицепсы'], ARRAY['Общий тонус', 'Выносливость']),
    ('burpee', 'Бёрпи', 'Из стойки перейдите в упор лёжа, вернитесь в присед и подпрыгните.', 'intermediate', ARRAY['Собственный вес'], ARRAY['Квадрицепсы', 'Ягодичные мышцы', 'Грудные мышцы'], ARRAY['Общий тонус', 'Выносливость']),
    ('high-knees', 'Бег на месте с высоким подниманием коленей', 'Чередуйте подъёмы коленей в беге на месте. За повтор считайте подъём правого колена.', 'beginner', ARRAY['Собственный вес'], ARRAY['Сгибатели бедра', 'Икроножные мышцы'], ARRAY['Общий тонус', 'Выносливость'])
), saved AS (
  INSERT INTO exercises(source, source_key, name, description, difficulty, equipment, goals)
  SELECT 'local', key, name, description, difficulty, equipment, goals FROM catalog
  ON CONFLICT (source, source_key) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty,
    equipment = EXCLUDED.equipment, goals = EXCLUDED.goals
  RETURNING id, source_key
)
INSERT INTO exercise_muscles(exercise_id, muscle_id)
SELECT saved.id, m.id FROM saved
JOIN catalog c ON c.key = saved.source_key
JOIN muscle_groups m ON m.name = ANY(c.muscles)
ON CONFLICT DO NOTHING;

COMMIT;
